#!/usr/bin/env bash
# Generated by pipeline/generate.py from the same DAG as Seq_Retail_DW_Master. Do not edit by hand.
# Runs the pipeline with dsjob: one wave per DAG level, jobs inside a wave run in parallel.
set -u
PROJECT="${DS_PROJECT:-RetailDW}"
pSrcDir="${pSrcDir:-C:/case_study/Source_Data}"
pStgDir="${pStgDir:-C:/case_study/Staging}"
pDwhDir="${pDwhDir:-C:/case_study/Warehouse}"
pMartDir="${pMartDir:-C:/case_study/Marts}"
pAuditDir="${pAuditDir:-C:/case_study/Audit}"
pRunDate="${pRunDate:-2011-12-31}"
pEffDate="${pEffDate:-2011-07-01}"
DSJOB="${DSJOB:-dsjob}"
FAILED=0
DIM_STATE=""

run_job() {  # dsjob -jobstatus: exit 1 = finished OK, 2 = finished with warnings
  local job="$1"; shift
  "$DSJOB" -run -jobstatus -mode NORMAL \
    -param pSrcDir="$pSrcDir" \
    -param pStgDir="$pStgDir" \
    -param pDwhDir="$pDwhDir" \
    -param pMartDir="$pMartDir" \
    -param pAuditDir="$pAuditDir" \
    -param pRunDate="$pRunDate" \
    -param pEffDate="$pEffDate" \
    "$PROJECT" "$job"
  local rc=$?
  if [ $rc -ne 1 ] && [ $rc -ne 2 ]; then echo "FAILED: $job (dsjob status $rc)" >&2; return 1; fi
  echo "OK: $job (status $rc)"
}

notify() { echo "NOTIFY: $1"; }  # replace with mail/Slack
trap 'notify "Retail DW pipeline FAILED for $pRunDate"' ERR

# ---- wave 0 ------------------------------------------------------------
mkdir -p $pStgDir $pDwhDir $pMartDir $pAuditDir

# ---- wave 1 ------------------------------------------------------------
until [ -f "$pSrcDir/orders_raw.csv" ]; do echo "waiting for $pSrcDir/orders_raw.csv"; sleep 30; done

# ---- wave 2 ------------------------------------------------------------
pids=()
( run_job J01_Land_Orders ) & pids+=($!)
( run_job J02_Land_Customers ) & pids+=($!)
( run_job J03_Land_Products ) & pids+=($!)
( run_job J04_Land_Stores_Employees ) & pids+=($!)
for p in "${pids[@]}"; do wait "$p" || FAILED=1; done
[ "$FAILED" -eq 0 ] || { notify "Retail DW pipeline FAILED for $pRunDate"; exit 1; }

# ---- wave 3 ------------------------------------------------------------

# ---- wave 4 ------------------------------------------------------------
DIM_STATE=$(test -f "$pDwhDir/dim_customer.csv" && echo EXISTS || echo MISSING)
pids=()
( run_job J07_Dim_Product ) & pids+=($!)
( run_job J08_Dim_Store_Employee ) & pids+=($!)
( run_job J09_Dim_Date_Promo_FX ) & pids+=($!)
for p in "${pids[@]}"; do wait "$p" || FAILED=1; done
[ "$FAILED" -eq 0 ] || { notify "Retail DW pipeline FAILED for $pRunDate"; exit 1; }

# ---- wave 5 ------------------------------------------------------------
pids=()
( if [ "$DIM_STATE" = "MISSING" ]; then run_job J05_Dim_Customer_Initial; else echo "SKIPPED: J05_Dim_Customer_Initial (dim_customer already exists)"; fi ) & pids+=($!)
for p in "${pids[@]}"; do wait "$p" || FAILED=1; done
[ "$FAILED" -eq 0 ] || { notify "Retail DW pipeline FAILED for $pRunDate"; exit 1; }

# ---- wave 6 ------------------------------------------------------------

# ---- wave 7 ------------------------------------------------------------
pids=()
( run_job J06_Dim_Customer_SCD2 ) & pids+=($!)
for p in "${pids[@]}"; do wait "$p" || FAILED=1; done
[ "$FAILED" -eq 0 ] || { notify "Retail DW pipeline FAILED for $pRunDate"; exit 1; }

# ---- wave 8 ------------------------------------------------------------
mv -f "$pDwhDir/dim_customer_next.csv" "$pDwhDir/dim_customer.csv"

# ---- wave 9 ------------------------------------------------------------

# ---- wave 10 ------------------------------------------------------------
pids=()
( run_job J10_Fact_Sales ) & pids+=($!)
( run_job J11_Fact_Returns ) & pids+=($!)
for p in "${pids[@]}"; do wait "$p" || FAILED=1; done
[ "$FAILED" -eq 0 ] || { notify "Retail DW pipeline FAILED for $pRunDate"; exit 1; }

# ---- wave 11 ------------------------------------------------------------
pids=()
( run_job J12_Fact_Invoice ) & pids+=($!)
for p in "${pids[@]}"; do wait "$p" || FAILED=1; done
[ "$FAILED" -eq 0 ] || { notify "Retail DW pipeline FAILED for $pRunDate"; exit 1; }

# ---- wave 12 ------------------------------------------------------------

# ---- wave 13 ------------------------------------------------------------
pids=()
( run_job J13_Mart_RETAIL_DATA_MART ) & pids+=($!)
( run_job J17_Mart_Customer_360 ) & pids+=($!)
( run_job J18_Mart_Product_Performance ) & pids+=($!)
( run_job J19_Mart_Basket_Affinity ) & pids+=($!)
( run_job J20_Mart_Store_Monthly ) & pids+=($!)
( run_job J21_Mart_Promo_Effectiveness ) & pids+=($!)
( run_job J22_DQ_Fact_Checks ) & pids+=($!)
( run_job J23_Reconcile_Source_To_Fact ) & pids+=($!)
for p in "${pids[@]}"; do wait "$p" || FAILED=1; done
[ "$FAILED" -eq 0 ] || { notify "Retail DW pipeline FAILED for $pRunDate"; exit 1; }

# ---- wave 14 ------------------------------------------------------------
pids=()
( run_job J14_Analysis_Employee_Transactions ) & pids+=($!)
( run_job J15_Analysis_CustomerType_Profit ) & pids+=($!)
( run_job J16_Bonus_Program ) & pids+=($!)
for p in "${pids[@]}"; do wait "$p" || FAILED=1; done
[ "$FAILED" -eq 0 ] || { notify "Retail DW pipeline FAILED for $pRunDate"; exit 1; }

# ---- wave 15 ------------------------------------------------------------

# ---- wave 16 ------------------------------------------------------------
notify "Retail DW pipeline succeeded for $pRunDate"

